import React from "react";
import './keyboard.css';

interface KeyboardProps {
    onKeyClick: (key: string) => void;
}

const Keyboard: React.FC<KeyboardProps> = ({ onKeyClick }) => {
    const rowonekeys = ['Q', 'W', 'E', 'R', 'T', 'Y', 'U', 'I', 'O', 'P'];
    const rowtwokeys = ['A', 'S', 'D', 'F', 'G', 'H', 'J', 'K', 'L'];
    const rowthreekeys = ['ENTER', 'Z', 'X', 'C', 'V', 'B', 'N', 'M', 'BACK'];

    const handleMouseClick = (letter: string) => {
        onKeyClick(letter);
    };

    return (
        <div className="keyboardcontainer">
            <div className="linecontainer">
                {rowonekeys.map((key) => (
                    <div key={key} onClick={() => handleMouseClick(key)}>
                        {key}
                    </div>
                ))}
            </div>
            <div className="linecontainer">
                {rowtwokeys.map((key) => (
                    <div key={key} onClick={() => handleMouseClick(key)}>
                        {key}
                    </div>
                ))}
            </div>
            <div className="linecontainer">
                {rowthreekeys.map((key) => (
                    <div key={key} onClick={() => handleMouseClick(key)}>
                        {key}
                    </div>
                ))}
            </div>
        </div>
    );
}

export default Keyboard;
